head.script:
scwin.gOvrdue_occr_dd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();

        // 패널라운드 처리
        // PanelToGroupBox(panel_1);

        // fn_SetCode();
        // fn_GetParentValue();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39202.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 연체발생일자
    scwin.gOvrdue_occr_dd = $c.frame.path("../").scwin.gOvrdue_occr_dd;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_list.errorMsg) {
            await $c.win.alert(dts_list.errorMsg);
        } else {

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39202.dts_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_list);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39202.dts_list_OnLoadError" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39202.img_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&CBPI_OVRDUE_OCCR_DD=" + scwin.gOvrdue_occr_dd;
    url += "&SCREN_ID=" + 'ULDSTF39202.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/CorpBndPrincInt.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
